create extension if not exists pgcrypto;
create table if not exists public.users(id uuid primary key references auth.users(id) on delete cascade,username text unique not null check(char_length(username) between 2 and 32),avatar text,created_at timestamptz default now());
create table if not exists public.books(id uuid primary key default gen_random_uuid(),title text not null,author text not null,description text,cover_url text not null,user_id uuid references public.users(id) on delete cascade,created_at timestamptz default now());
create table if not exists public.ratings(id uuid primary key default gen_random_uuid(),book_id uuid references public.books(id) on delete cascade,user_id uuid references public.users(id) on delete cascade,rating smallint check(rating between 1 and 10),created_at timestamptz default now(),unique(book_id,user_id));
create table if not exists public.comments(id uuid primary key default gen_random_uuid(),book_id uuid references public.books(id) on delete cascade,user_id uuid references public.users(id) on delete cascade,text text not null,created_at timestamptz default now());
alter table public.users enable row level security;alter table public.books enable row level security;alter table public.ratings enable row level security;alter table public.comments enable row level security;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.users(id,username) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'username',''),'user_'||substr(new.id::text,1,8))) on conflict(id) do nothing;return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
drop policy if exists "profiles readable" on public.users;create policy "profiles readable" on public.users for select using(true);drop policy if exists "own profile update" on public.users;create policy "own profile update" on public.users for update using(auth.uid()=id);
drop policy if exists "books readable" on public.books;create policy "books readable" on public.books for select using(true);drop policy if exists "owners create books" on public.books;create policy "owners create books" on public.books for insert with check(auth.uid()=user_id);drop policy if exists "ratings readable" on public.ratings;create policy "ratings readable" on public.ratings for select using(true);drop policy if exists "own rating" on public.ratings;create policy "own rating" on public.ratings for all using(auth.uid()=user_id) with check(auth.uid()=user_id);drop policy if exists "comments readable" on public.comments;create policy "comments readable" on public.comments for select using(true);drop policy if exists "own comments" on public.comments;create policy "own comments" on public.comments for all using(auth.uid()=user_id) with check(auth.uid()=user_id);